import XCTest
@testable import iPadn

/// Vectors generated from the reference Python implementation
/// (gen_vectors.py) using synthetic, non-account material only: a fake
/// SINF whose priv record was built for a random test credential, a fake
/// SUPF, and a tiny synthetic Mach-O encrypted with the derived keys.
final class FairPlayDecryptorTests: XCTestCase {
    private func data(_ base64: String) -> Data { Data(base64Encoded: base64)! }

    func testFinishVector() {
        let input: [UInt16] = [8597, 21221, 43188, 1177, 24931, 41778, 50858, 45530]
        let expected: [UInt16] = [32511, 19723, 25488, 28832, 24235, 49330, 7211, 44309]
        XCTAssertEqual(FairPlayDecryptor.finish(input), expected)
    }

    func testDerivePageKeyVector() throws {
        let key = try FairPlayDecryptor.derivePageKey(
            wrapped: data("MxW2+N8Gu41b9sajdrQGNg=="),
            absoluteIndex: 12345,
            work: data("m4azPgYMOODnvFHjfFkKdw=="))
        XCTAssertEqual(key, data("Uvn5K6OH9v379gyWc9lobA=="))
    }

    func testDeriveWork16Vector() throws {
        let work = try FairPlayDecryptor.deriveWork16(
            credential: data("ypnlqHnVeKBms8lq0MK66Q=="),
            sinf: data(""))
        XCTAssertEqual(work, data("tiiLZbYpTPFj11x25ZRcWA=="))
    }

    func testSupfRecordOffsetVector() throws {
        let offset = try FairPlayDecryptor.supfRecordOffset(
            supf: data("BTUwNwAAAAAAAAABAAAATAEAAAwAAAAHAAAAAktGg2UtTDS6OIUkVNTFC6HRZIFQAZFqK56kBs/YVmh7ujFtxEW/7aHE08g2OlBV53b2B3/9R4J988iOhitdaXY="), requiredPages: 2, wantedSubtype: 7)
        XCTAssertEqual(offset, 28)
    }

    func testDecryptBinaryEndToEnd() throws {
        let (result, pages) = try FairPlayDecryptor.decryptBinary(
            source: data(""),
            sinf: data(""),
            supf: data("BTUwNwAAAAAAAAABAAAATAEAAAwAAAAHAAAAAktGg2UtTDS6OIUkVNTFC6HRZIFQAZFqK56kBs/YVmh7ujFtxEW/7aHE08g2OlBV53b2B3/9R4J988iOhitdaXY="),
            credential: data("ypnlqHnVeKBms8lq0MK66Q=="))
        XCTAssertEqual(pages, 2)
        XCTAssertEqual(FairPlayDecryptor.subdata(result, 4096, 8192), data(""))
        XCTAssertTrue(try FairPlayDecryptor.encryptionInfos(in: result).isEmpty)
    }

    func testWrongCredentialIsRejected() {
        var wrong = data("ypnlqHnVeKBms8lq0MK66Q==")
        wrong[0] ^= 0xFF
        XCTAssertThrowsError(try FairPlayDecryptor.deriveWork16(
            credential: wrong, sinf: data("")))
    }
}
